    Bug 2036164 - Modify a copy of the oauth provider in the case it needs to be modified. r=jtracey,darktrojan

    Differential Revision: https://phabricator.services.mozilla.com/D297737

diff --git a/mailnews/base/src/OAuth2Providers.sys.mjs b/mailnews/base/src/OAuth2Providers.sys.mjs
index 291d3df314d..9c187fee145 100644
--- a/mailnews/base/src/OAuth2Providers.sys.mjs
+++ b/mailnews/base/src/OAuth2Providers.sys.mjs
@@ -440,19 +440,21 @@ export var OAuth2Providers = {
    * @returns {?IssuerDetails}
    */
   getIssuerDetails(issuer) {
-    const details = kIssuers.get(issuer);
+    let details = kIssuers.get(issuer);
     // We have a separate sandbox for prototyping OAuth scopes on Microsoft 365.
-    if (issuer == "login.microsoftonline.com") {
-      const useMicrosoft365Sandbox = Services.prefs.getBoolPref(
-        "mail.microsoft.useM365Sandbox",
-        false
-      );
-      if (useMicrosoft365Sandbox) {
+    const useMicrosoft365Sandbox = Services.prefs.getBoolPref(
+      "mail.microsoft.useM365Sandbox",
+      false
+    );
+    if (useMicrosoft365Sandbox) {
+      if (issuer == "login.microsoftonline.com") {
+        details = structuredClone(details);
         details.clientId = "b00dc6cb-0459-4bd4-ac0d-2e23516f906a";
         const microsoft365SandboxTenantId =
           "aead8f37-924c-4d3f-9f20-494295c72956";
         details.authorizationEndpoint = `https://login.microsoftonline.com/${microsoft365SandboxTenantId}/oauth2/v2.0/authorize`;
         details.tokenEndpoint = `https://login.microsoftonline.com/${microsoft365SandboxTenantId}/oauth2/v2.0/token`;
+        Object.freeze(details);
       }
     }
     return details;
diff --git a/mailnews/base/test/unit/test_oAuth2Providers.js b/mailnews/base/test/unit/test_oAuth2Providers.js
index f32ed4ec6f5..179045f8753 100644
--- a/mailnews/base/test/unit/test_oAuth2Providers.js
+++ b/mailnews/base/test/unit/test_oAuth2Providers.js
@@ -332,3 +332,31 @@ add_task(function testStringScopesWithoutExchangeSupport() {
     }
   }
 });
+
+add_task(function testGetIssuerMicrosoft() {
+  const details = OAuth2Providers.getIssuerDetails("login.microsoftonline.com");
+
+  Assert.ok(Object.isFrozen(details), "OAuth details should be frozen.");
+
+  Assert.equal(
+    details.clientId,
+    "9e5f94bc-e8a4-4e73-b8be-63364c29d753",
+    "Should be using the production client ID by default."
+  );
+});
+
+add_task(function testGetIssuerMicrosoftSandboxModification() {
+  Services.prefs.setBoolPref("mail.microsoft.useM365Sandbox", true);
+
+  const details = OAuth2Providers.getIssuerDetails("login.microsoftonline.com");
+
+  Assert.ok(Object.isFrozen(details), "OAuth details should be frozen.");
+
+  Assert.equal(
+    details.clientId,
+    "b00dc6cb-0459-4bd4-ac0d-2e23516f906a",
+    "Should be using the Sandbox client ID when the sandbox preference is set."
+  );
+
+  Services.prefs.setBoolPref("mail.microsoft.useM365Sandbox", false);
+});
